<script setup>
import { computed, ref } from 'vue'
import { actionConfirmationAllowed, assistantSafeDetails } from '../services/admin-assistant.js'
import AssistantTemplateReview from './AssistantTemplateReview.vue'
const props = defineProps({ action: { type: Object, required: true }, busy: Boolean, executeAllowed: { type: Boolean, default: true } })
const emit = defineEmits(['confirm','cancel','revise'])
const reviewed=ref(false),phrase=ref('')
const destructive=computed(()=>Boolean(props.action.destructive||props.action.confirmationText))
const allowed=computed(()=>props.executeAllowed&&!props.busy&&actionConfirmationAllowed(props.action,{reviewed:reviewed.value,phrase:phrase.value}))
const preview=computed(()=>JSON.stringify(assistantSafeDetails(props.action.preview||{}),null,2))
</script>
<template><section class="assistant-action" :class="{'assistant-action--destructive':destructive}" aria-label="Revisão de ação"><header><q-icon :name="destructive?'warning_amber':'fact_check'" size="23px"/><div class="assistant-action__heading"><strong>{{action.title || 'Revisar ação'}}</strong><small>{{action.status==='pending'?'Aguardando sua confirmação':action.status==='executing'?'Executando…':action.status==='succeeded'?'Concluído':action.status==='cancelled'?'Cancelado':action.status==='failed'?'Falhou':action.status}}</small></div><q-badge v-if="destructive" color="negative">Remoção de dados</q-badge></header><AssistantTemplateReview v-if="action.preview?.template||action.preview?.cloneSource||action.preview?.warnings?.length" :preview="action.preview"/><q-expansion-item v-if="action.preview?.template" dense icon="data_object" label="Ver os dados do cadastro"><pre>{{preview}}</pre></q-expansion-item><pre v-else>{{preview}}</pre><q-banner v-if="action.error" dense class="assistant-action__error">{{action.error}}</q-banner><template v-if="action.status==='pending'"><p v-if="!executeAllowed">Seu perfil não tem permissão para executar ações pelo agente.</p><p>Confira os dados, o canal e os destinatários. Esta ação só será executada após a confirmação.</p><q-checkbox v-model="reviewed" dense color="primary" label="Revisei os dados desta ação" :disable="busy"/><div v-if="action.confirmationText" class="assistant-action__phrase"><label>Para autorizar a remoção, digite exatamente:</label><code>{{action.confirmationText}}</code><q-input v-model="phrase" outlined dense autocomplete="off" spellcheck="false" label="Frase de confirmação" :disable="busy" @paste.prevent/></div><footer><q-btn flat no-caps label="Cancelar" :disable="busy" @click="emit('cancel',action)"/><q-btn flat no-caps icon="edit" label="Pedir ajuste" :disable="busy" @click="emit('revise',action)"/><q-btn unelevated no-caps :color="destructive?'negative':'primary'" :icon="destructive?'delete_forever':'check'" label="Confirmar ação" :disable="!allowed" :loading="busy" @click="emit('confirm',{actionId:action.id,confirmationText:phrase||undefined})"/></footer></template></section></template>
<style scoped>.assistant-action{padding:17px;border:1px solid var(--aito-line);border-radius:16px;background:var(--aito-panel);margin:18px 0;color:var(--aito-text)}.assistant-action--destructive{border-color:#d99b9b;background:#fff4f4}.assistant-action header{display:flex;align-items:center;gap:10px}.assistant-action__heading{flex:1;min-width:0}.assistant-action header strong{display:block;font-size:14px;overflow-wrap:anywhere;line-height:1.5}.assistant-action header small{color:var(--aito-muted);font-size:11px}.assistant-action header .q-icon{color:var(--aito-accent)}.assistant-action--destructive header .q-icon{color:#b23939}.assistant-action pre{font-size:11px;line-height:1.7;padding:12px;background:var(--aito-code);max-height:280px;overflow:auto;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere}.assistant-action p{font-size:12px;line-height:1.6;color:var(--aito-muted);margin:12px 0}.assistant-action :deep(.q-checkbox__label){font-size:12px}.assistant-action__phrase{display:grid;gap:10px;margin-top:15px;font-size:12px}.assistant-action__phrase code{padding:10px;background:#fff0ee;color:#8c302a;border-radius:8px;overflow-wrap:anywhere}.assistant-action footer{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:5px;margin-top:15px}.assistant-action footer .q-btn{font-size:12px}.assistant-action__error{margin-top:12px;background:#fff0ee;color:#8c302a;font-size:12px}@media(max-width:600px){.assistant-action{padding:13px}.assistant-action header{flex-wrap:wrap}.assistant-action footer{display:grid;grid-template-columns:1fr 1fr}.assistant-action footer>.q-btn:last-child{grid-column:1/-1}}</style>
